const atlasById=new Map(atlasEntries.map(e=>[e.id,e]));
const atlasKinds={place:'巴黎记忆',person:'具名人物',group:'人物群体'};
let atlasState={kind:'all',query:'',category:'all',selected:'place-vivienne',zoom:1,x:0,y:0},dossierLimit=8;
const atlasMatches=e=>e.matches.map(m=>({c:bookById.get(m.chapter),p:bookById.get(m.chapter).paragraphs[m.pos],i:m.pos}));
const entryImage=e=>artwork[e.image]?.file||artwork.library.file;
function entryVisual(e,cls=''){let exact=['vivienne','vero','panoramas','caire','opera','baudelaire','fourier','haussmann','grandville','benjamin','daguerre'].includes(e.id.replace(/^(place|person)-/,''));return `<figure class="atlas-art ${cls}"><img src="${entryImage(e)}" alt="${esc(exact?e.name+' · '+artwork[e.image].title:e.name+'相关主题配图：'+artwork[e.image]?.title)}" loading="lazy"><figcaption>${esc(exact?artwork[e.image].credit:'主题配图 · '+(artwork[e.image]?.credit||''))}</figcaption></figure>`}
function archiveCard(e){return `<a class="atlas-card tone-${atlasEntries.indexOf(e)%7}" href="#dossier/${e.id}">${entryVisual(e)}<div class="atlas-card-copy"><span>${esc(e.category)}</span><h2>${esc(e.name)}</h2><p>${esc(e.en)}</p><div>${e.matches.length} 段材料 <span>打开档案 ↗</span></div></div></a>`}
function expandedTopic(kind){let list=atlasEntries.filter(e=>kind==='place'?e.kind==='place':e.kind!=='place');return `<section class="section atlas-topic"><div class="topic-heading"><div><p>${kind==='place'?'Mémoire des lieux':'Figures et visages'}</p><h1>${kind==='place'?'巴黎记忆':'巴黎人物'}</h1></div><div><p>${kind==='place'?'35处地点，沿着街道与残片阅读城市。':'42位具名人物与15类群体，让城市拥有面孔。'}</p><a href="#atlas/${kind}" class="primary-link">在地图中探索 ↗</a></div></div><div class="archive-controls"><label>查找档案<input id="topic-search" type="search" placeholder="输入地点、人物或关键词"></label><label>类别<select id="topic-category"><option value="all">所有类别</option>${[...new Set(list.map(e=>e.category))].map(c=>`<option>${esc(c)}</option>`).join('')}</select></label></div><p id="topic-count" aria-live="polite">${list.length} 份档案</p><div id="topic-results" class="atlas-card-grid">${list.map(archiveCard).join('')}</div></section>`}
memoryPage=()=>expandedTopic('place');charactersPage=()=>expandedTopic('person');figuresPage=()=>expandedTopic('person');
function projected(e){return {x:(e.lon-2.286)/.104*100,y:(48.893-e.lat)/.068*100}}
const riverPath='M-30 550 C100 610 120 470 250 450 S380 450 445 420 S550 345 650 375 S850 490 1030 270';
function atlasBase(){return `<svg viewBox="0 0 1000 680" preserveAspectRatio="none" aria-hidden="true"><defs><filter id="map-paper"><feTurbulence type="fractalNoise" baseFrequency=".025 .09" numOctaves="3" seed="12"/><feColorMatrix type="saturate" values="0"/><feComponentTransfer><feFuncA type="linear" slope=".14"/></feComponentTransfer><feBlend in="SourceGraphic" mode="multiply"/></filter></defs><rect width="1000" height="680" fill="#c2bdad"/><g filter="url(#map-paper)" opacity=".85"><path d="M0 0H420L390 180 250 275 0 230Z" fill="#aeb7a4"/><path d="M420 0H800L750 260 510 300 390 180Z" fill="#baa7aa"/><path d="M800 0H1000V290L750 260Z" fill="#b0b6bf"/><path d="M0 230L250 275 400 420 150 540 0 500Z" fill="#c1af9a"/><path d="M250 275L510 300 660 395 400 420Z" fill="#d0c6b5"/><path d="M0 500L150 540 400 420 650 475 580 680H0Z" fill="#aaa994"/><path d="M660 395L1000 290V680H580L650 475Z" fill="#b5a8b0"/></g><g stroke="#e7dfcd" opacity=".55" fill="none" stroke-width="4"><path d="M50 100L880 600M180 0L620 680M450 0L420 680M0 320L1000 230M0 180L1000 530M740 0L580 680M0 540L1000 90M150 0L220 680"/></g><path d="${riverPath}" stroke="#8e9fa4" stroke-width="35" fill="none"/><path d="${riverPath}" stroke="#c7d0c9" stroke-width="2" fill="none" opacity=".4"/><g fill="#666e66" font-family="Georgia,serif" font-style="italic" font-size="20" opacity=".65"><text x="140" y="170">Les passages</text><text x="390" y="530">La Seine</text><text x="600" y="220">Le Paris des foules</text><text x="170" y="610">La rive gauche</text></g></svg>`}
function atlasPage(){return `<section class="atlas-explorer"><div class="atlas-heading"><div><p>Une ville, des constellations</p><h1>巴黎，记忆的星丛。</h1></div><p>地点、人物与群体，在书页中相遇。<br><small>油画示意底图 · 现存地标坐标仅供索引</small></p></div><div class="atlas-toolbar"><div role="group" aria-label="地图内容">${[['all','全部'],['place','地点'],['person','人物'],['group','群体']].map(([k,t])=>`<button data-map-kind="${k}" aria-pressed="${atlasState.kind===k}">${t}</button>`).join('')}</div><label class="atlas-search-label">查找线索<input id="atlas-search" type="search" value="${esc(atlasState.query)}" placeholder="例如：雨果、拱廊、收藏家"></label></div><div class="atlas-workspace"><div class="atlas-map-column"><div class="map-viewport" id="map-viewport" tabindex="0" role="region" aria-label="巴黎地图，可拖动；方向键平移，加减键缩放，Home复位"><div id="map-stage" class="map-stage"><div class="map-base">${atlasBase()}</div><div id="map-markers"></div></div><div class="map-legend"><span>● 地点</span><span>◆ 同段人物线索</span></div><div class="map-controls"><button data-map-action="in" aria-label="放大地图">＋</button><button data-map-action="out" aria-label="缩小地图">−</button><button data-map-action="reset">复位</button></div><span class="map-north">N ↑</span></div><div id="map-status" class="map-status" aria-live="polite"></div><p class="atlas-caution">点选标记或下方档案。人物落在其相关地点的索引节点上；“同段提及”不代表曾居住或活动于此。消失或未准确定位的地点收于档案列表。</p></div><aside id="atlas-panel" class="atlas-panel" aria-label="选中档案"></aside></div><div class="atlas-results-heading"><h2>档案索引</h2><span id="atlas-result-count" aria-live="polite"></span></div><div id="atlas-index" class="atlas-index"></div></section>`}
function filteredAtlas(){let q=atlasState.query.trim().toLowerCase();return atlasEntries.filter(e=>(atlasState.kind==='all'||e.kind===atlasState.kind)&&(!q||[e.name,e.en,e.category,e.description,...e.terms].join(' ').toLowerCase().includes(q)))}
function atlasPersonPins(list){let used=new Map();return list.filter(e=>e.kind!=='place').map(e=>{let place=e.related.map(r=>atlasById.get(r.id)).find(p=>p?.lat);if(!place)return '';let n=used.get(place.id)||0;used.set(place.id,n+1);let pos=projected(place),x=pos.x+2+(n%3)*2,y=pos.y-2-Math.floor(n/3)*2;return `<button class="map-pin map-person-pin ${atlasState.selected===e.id?'active':''} tone-${atlasEntries.indexOf(e)%7}" style="left:${x}%;top:${y}%" data-atlas-select="${e.id}" aria-label="${esc(e.name)}，与${esc(place.name)}在文档同段提及"><i></i><span>${esc(e.name)}<small>文字关联：${esc(place.name)}</small></span></button>`}).join('')}
function updateAtlas(){let list=filteredAtlas(),selected=atlasById.get(atlasState.selected);document.querySelector('#atlas-index').innerHTML=list.map(e=>`<button class="atlas-index-entry ${selected?.id===e.id?'selected':''} tone-${atlasEntries.indexOf(e)%7}" data-atlas-select="${e.id}"><span>${atlasKinds[e.kind]}</span><strong>${e.name}</strong><small>${e.matches.length} 段材料 ${e.kind==='place'&&!e.lat?'· 未落点':''}</small></button>`).join('')||'<p>没有匹配档案，请试试其他关键词。</p>';document.querySelector('#atlas-result-count').textContent=list.length+' 份档案';document.querySelectorAll('[data-map-kind]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mapKind===atlasState.kind)));
 let selectedPlaces=new Set(selected?.kind==='place'?[selected.id]:selected?.related.map(x=>x.id)||[]);let locations=atlasEntries.filter(e=>e.kind==='place'&&e.lat);let visible=locations.filter(p=>list.some(e=>e.id===p.id||e.related.some(r=>r.id===p.id)));document.querySelector('#map-markers').innerHTML=visible.map(p=>{let pos=projected(p),active=selectedPlaces.has(p.id),who=p.related.filter(r=>list.some(e=>e.id===r.id));return `<button class="map-pin ${active?'active':''} tone-${atlasEntries.indexOf(p)%7}" style="left:${pos.x}%;top:${pos.y}%" data-atlas-select="${p.id}" aria-label="${esc(p.name)}，${p.matches.length}段材料，${who.length}条人物线索"><i></i><span>${esc(p.name)}${who.length?' <b>◆'+who.length+'</b>':''}</span></button>`}).join('');document.querySelector('#map-status').textContent=visible.length+' 个有坐标的地点节点 · '+list.filter(e=>e.kind==='place'&&!e.lat).length+' 个未落点地点 · 可拖动与缩放';document.querySelector('#map-markers').insertAdjacentHTML('beforeend',atlasPersonPins(list));showAtlasPanel(selected);bindSelect();applyMapTransform()}
function showAtlasPanel(e){if(!e)return;let h=atlasMatches(e)[0],links=e.related.map(r=>atlasById.get(r.id));document.querySelector('#atlas-panel').innerHTML=`${entryVisual(e,'panel-art')}<div class="atlas-panel-body"><p class="panel-kind">${atlasKinds[e.kind]} · ${e.category}</p><h2>${e.name}</h2><p class="panel-en">${e.en}</p><p>${e.description}</p><a class="primary-link" href="#dossier/${e.id}">查看完整档案 ↗</a><h3>书中的一处痕迹</h3><blockquote>${esc(h.p.slice(0,220))}${h.p.length>220?'…':''}</blockquote><a class="panel-source" href="#read/${h.c.id}/${h.i}">${h.c.title} ↗</a>${links.length?`<h3>同段相遇</h3><div class="atlas-related">${links.slice(0,10).map(x=>`<button data-atlas-select="${x.id}">${x.name} ↗</button>`).join('')}</div><p class="note">关联来自同段文字，不构成生平或空间事实的断言。</p>`:''}${e.geoSource?`<a href="${e.geoSource}" target="_blank" rel="noopener" class="geo-source">地标坐标资料 ↗</a>`:e.kind==='place'?'<p class="note">尚未设置可靠坐标，保留文字档案。</p>':''}</div>`}
function bindSelect(){document.querySelectorAll('[data-atlas-select]').forEach(b=>b.onclick=()=>{atlasState.selected=b.dataset.atlasSelect;updateAtlas();document.querySelector('#atlas-panel')?.animate?.([{opacity:.4,transform:'translateY(12px)'},{opacity:1,transform:'none'}],{duration:matchMedia('(prefers-reduced-motion: reduce)').matches?0:400});if(innerWidth<850)document.querySelector('#atlas-panel').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})})}
function applyMapTransform(){let el=document.querySelector('#map-stage');if(el)el.style.transform=`translate(${atlasState.x}px,${atlasState.y}px) scale(${atlasState.zoom})`}
function bindMap(){document.querySelector('#atlas-search').oninput=e=>{atlasState.query=e.target.value;updateAtlas()};document.querySelectorAll('[data-map-kind]').forEach(b=>b.onclick=()=>{atlasState.kind=b.dataset.mapKind;updateAtlas()});const action=a=>{if(a==='reset'){atlasState.zoom=1;atlasState.x=atlasState.y=0}else atlasState.zoom=Math.min(3,Math.max(.8,atlasState.zoom+(a==='in'?.25:-.25)));applyMapTransform()};document.querySelectorAll('[data-map-action]').forEach(b=>b.onclick=()=>action(b.dataset.mapAction));let view=document.querySelector('#map-viewport'),drag=null;view.onpointerdown=e=>{if(e.target.closest('button'))return;drag={x:e.clientX,y:e.clientY,ox:atlasState.x,oy:atlasState.y};view.setPointerCapture(e.pointerId);view.classList.add('dragging')};view.onpointermove=e=>{if(!drag)return;atlasState.x=Math.max(-900,Math.min(900,drag.ox+e.clientX-drag.x));atlasState.y=Math.max(-650,Math.min(650,drag.oy+e.clientY-drag.y));applyMapTransform()};const stop=()=>{drag=null;view.classList.remove('dragging')};view.onpointerup=stop;view.onpointercancel=stop;view.onkeydown=e=>{if(e.target!==view)return;let keys=['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-','=','Home'];if(!keys.includes(e.key))return;e.preventDefault();if(e.key==='Home')action('reset');else if(['+','-','='].includes(e.key))action(e.key==='-'?'out':'in');else{atlasState.x+=e.key==='ArrowLeft'?40:e.key==='ArrowRight'?-40:0;atlasState.y+=e.key==='ArrowUp'?40:e.key==='ArrowDown'?-40:0;applyMapTransform()}};updateAtlas()}
function bindTopic(kind){let input=document.querySelector('#topic-search'),select=document.querySelector('#topic-category');if(!input||!select)return;let update=()=>{let q=input.value.trim().toLowerCase(),list=atlasEntries.filter(e=>(kind==='place'?e.kind==='place':e.kind!=='place')&&(select.value==='all'||e.category===select.value)&&[e.name,e.en,e.category,e.description,...e.terms].join(' ').toLowerCase().includes(q));document.querySelector('#topic-results').innerHTML=list.map(archiveCard).join('')||'<p>未找到匹配档案。</p>';document.querySelector('#topic-count').textContent=list.length+' 份档案'};input.oninput=update;select.onchange=update}
function dossierPage(id){let e=atlasById.get(id);if(!e)return '<section class="section"><h1>档案未找到</h1><a class="primary-link" href="#atlas">返回地图</a></section>';let related=e.related.map(r=>({entry:atlasById.get(r.id),r}));return `<section class="section dossier"><a class="back-link" href="#atlas/${e.kind}">← 巴黎地图</a><div class="dossier-hero tone-${atlasEntries.indexOf(e)%7}">${entryVisual(e)}<div><p>${atlasKinds[e.kind]} · ${e.category}</p><h1>${e.name}</h1><p>${e.en}</p><p>${e.description}</p><small>${e.sourceNote}</small></div></div>${related.length?`<section class="dossier-links"><h2>文字中的相遇</h2><p class="note">以下对象与本档案在同段导览中出现，点击可交叉索引。</p><div class="atlas-related">${related.map(({entry:x,r})=>`<a href="#dossier/${x.id}">${x.name} <small>${r.count}段</small> ↗</a>`).join('')}</div></section>`:''}<section class="dossier-records"><h2>卷轴中的痕迹</h2><p class="note">${e.matches.length} 段匹配材料；下列为所提供导览的摘录与解读，引用版本待核对。</p><div id="dossier-records"></div><button id="dossier-more">继续展开材料</button></section>${e.geoSource?`<p class="note">${e.geoNote} · <a href="${e.geoSource}" target="_blank" rel="noopener">坐标资料 ↗</a></p>`:''}</section>`}
function fillDossier(id){let e=atlasById.get(id);if(!e)return;let all=atlasMatches(e);document.querySelector('#dossier-records').innerHTML=all.slice(0,dossierLimit).map(h=>`<blockquote class="group-excerpt"><p>${esc(h.p)}</p><a class="excerpt-link" href="#read/${h.c.id}/${h.i}">${h.c.title}<span>进入卷轴 ↗</span></a></blockquote>`).join('');let more=document.querySelector('#dossier-more');more.hidden=dossierLimit>=all.length;more.textContent='继续展开材料（'+Math.min(dossierLimit,all.length)+' / '+all.length+'）';more.onclick=()=>{dossierLimit+=10;fillDossier(id)}}
const atlasHomeOriginal=home;
home=function(){return `<section class="morandi-hero"><div class="morandi-panorama"><img src="assets/morandi-panorama.jpg" alt="莫兰迪色调的十九世纪巴黎油画全景，艺术演绎"></div><div class="morandi-hero-copy"><p>瓦尔特·本雅明 · 拱廊街计划</p><h1>在巴黎，<br>拾起历史。</h1><p>街道、面孔与未醒的梦。<br>一座城市的记忆，在碎片中相连。</p><div class="hero-actions"><a class="primary-link" href="#atlas">打开巴黎地图 ↗</a><a href="#library" class="secondary-link">进入全书导览 ↗</a></div></div><div class="hero-palette" aria-label="莫兰迪色谱"><span></span><span></span><span></span><span></span><span></span><span></span><span></span></div><p class="hero-image-credit">巴黎全景 · AI 艺术演绎</p></section><section class="section atlas-home-intro"><h2>一座城市，<br>许多种相遇。</h2><div><p>35处地点、42位具名人物、15类群体。沿着地图走进一段文字，再由文字走向另一处记忆。</p><a class="primary-link" href="#atlas">开始探索 ↗</a><p class="note">地点定位与人物线索分层呈现。</p></div></section><section class="section"><div class="section-heading"><h2>巴黎记忆</h2><a href="#memory">全部地点 ↗</a></div><div class="atlas-card-grid home-atlas-cards">${atlasEntries.filter(e=>e.kind==='place').slice(0,6).map(archiveCard).join('')}</div></section><section class="section"><div class="section-heading"><h2>巴黎人物</h2><a href="#characters">全部人物与群体 ↗</a></div><div class="atlas-card-grid home-atlas-cards">${['group-flaneur','person-baudelaire','group-ragpicker','person-hugo','group-collector','person-aragon'].map(id=>archiveCard(atlasById.get(id))).join('')}</div></section><section class="section volume-teaser"><h2>全书导览</h2><p>七个部分，三十六个主题卷轴。</p>${links(chapters.filter(c=>['A','C','J','M'].includes(c.code)))}<a class="primary-link" href="#library">浏览全书目录 ↗</a></section>`};
const atlasRenderOriginal=render;
render=function(){let [route,id]=decodeURI(location.hash.slice(1)).split('/');if(route==='atlas'){if(['place','person','group'].includes(id))atlasState.kind=id;document.querySelector('#app').innerHTML=atlasPage();window.scrollTo(0,0);bindMap()}else if(route==='dossier'){dossierLimit=8;document.querySelector('#app').innerHTML=dossierPage(id);window.scrollTo(0,0);fillDossier(id)}else{atlasRenderOriginal();if(['memory','places'].includes(route))bindTopic('place');if(['characters','people','figures'].includes(route))bindTopic('person')}
 let nav=document.querySelector('header nav');if(nav)nav.innerHTML='<a href="#atlas" class="nav-map">巴黎地图</a><a href="#memory">巴黎记忆</a><a href="#characters">巴黎人物</a><a href="#library" class="nav-library">全书导览 ↗</a><a href="#notebook">札记</a>';if(route==='sources')document.querySelector('.section')?.insertAdjacentHTML('beforeend',`<h2>巴黎地图与扩展档案</h2><p>35个地点、42位具名人物、15类人物群体依据导览中实际出现的名称建立索引。人物与地点的关联由同段文字交集生成，不能单独证明人物曾在该地活动。23个现存地标的坐标由法语维基百科条目核对；历史对象、区域与缺少可靠坐标的地点不强行落点。底图为油画配色的地理示意，不用于导航。扩展条目的图片多数为主题配图，不冒充人物肖像或地点实景。</p><div class="geo-credits">${atlasEntries.filter(e=>e.geoSource).map(e=>`<a href="${e.geoSource}" target="_blank" rel="noopener">${e.name} · 坐标来源 ↗</a>`).join('')}</div><p>莫兰迪巴黎全景为内置 imagegen 生成的艺术演绎。</p>`)
};
const atlasMotionRoot=document.querySelector('#app');
atlasMotionRoot.addEventListener('pointermove',e=>{if(e.pointerType==='touch'||document.body.classList.contains('motion-off')||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const card=e.target.closest('.atlas-card');if(!card)return;let r=card.getBoundingClientRect();card.style.setProperty('--ry',((e.clientX-r.left)/r.width-.5)*4+'deg');card.style.setProperty('--rx',-((e.clientY-r.top)/r.height-.5)*4+'deg')});
atlasMotionRoot.addEventListener('pointerout',e=>{const card=e.target.closest('.atlas-card');if(card&&!card.contains(e.relatedTarget)){card.style.setProperty('--rx','0deg');card.style.setProperty('--ry','0deg')}});
removeEventListener('hashchange',atlasRenderOriginal);addEventListener('hashchange',render);render();
